// Watch /volume1/PoeTech/bank-imports/ (mounted in n8n container at
// /data/bank-imports) for new .ofx, .qfx, or .csv files. Parse each into
// a normalized transaction array and dump per-transaction JSON files in
// /data/finance-events/bank/<institution>/.
//
// PHASE 2B (2026-05-28): ALSO extracts LEDGERBAL/AVAILBAL/DTASOF/ACCTID
// from each OFX/QFX file and writes /data/finance-events/bank/<inst>/_balance.json
// so the PWA can show bank-authoritative balances on the Accounts tab
// (not just the sum of transactions, which doesn't equal balance without
// an opening balance).
//
// Backfill pass: on every run, scan /data/finance-events/bank/<inst>/ for
// institutions missing _balance.json and try to read the matching archived
// file from _processed/ to populate it. This means existing institutions
// get balance data the next time this workflow runs — no need to re-drop
// the QFX files manually.
//
// Convention: filename starts with institution slug (e.g. chase8168_*.qfx).
// The slug before the first '-' or '_' is the institution. Subfolders work.

const fs = require('fs');
const path = require('path');

const IN_DIR = '/data/bank-imports';
const OUT_DIR = '/data/finance-events/bank';
const PROCESSED_DIR = path.join(IN_DIR, '_processed');

try { fs.mkdirSync(IN_DIR, { recursive: true }); } catch (_) {}
try { fs.mkdirSync(OUT_DIR, { recursive: true }); } catch (_) {}
try { fs.mkdirSync(PROCESSED_DIR, { recursive: true }); } catch (_) {}

function walk(dir, out) {
  let entries;
  try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch (_) { return; }
  for (const e of entries) {
    if (e.name.startsWith('_')) continue;
    const full = path.join(dir, e.name);
    if (e.isDirectory()) walk(full, out);
    else if (/\.(ofx|qfx|csv)$/i.test(e.name)) out.push(full);
  }
}

function parseOFX(text) {
  // Minimal OFX parser — works on both OFX 1.x (SGML) and 2.x (XML).
  // Extracts STMTTRN blocks: TRNAMT, DTPOSTED, NAME/MEMO, FITID, TRNTYPE.
  const txs = [];
  const block = /<STMTTRN>([\s\S]*?)<\/STMTTRN>/gi;
  let m;
  while ((m = block.exec(text))) {
    const seg = m[1];
    function tag(name) {
      const r = new RegExp('<' + name + '>([^<\\r\\n]+)', 'i').exec(seg);
      return r ? r[1].trim() : null;
    }
    const dt = tag('DTPOSTED');
    let posted = null;
    if (dt) {
      const y = dt.slice(0, 4), mo = dt.slice(4, 6), d = dt.slice(6, 8);
      posted = `${y}-${mo}-${d}`;
    }
    const amt = tag('TRNAMT');
    txs.push({
      fitid: tag('FITID'),
      type: tag('TRNTYPE'),
      amount: amt ? parseFloat(amt) : null,
      posted,
      name: tag('NAME') || tag('MEMO'),
      memo: tag('MEMO')
    });
  }
  return txs;
}

function parseOFXBalance(text) {
  // Phase 2B — extract bank-authoritative balance + account metadata
  // from an OFX/QFX file. Returns the structured info that goes into
  // _balance.json for that institution.
  function tagGlobal(name) {
    const r = new RegExp('<' + name + '>([^<\\r\\n]+)', 'i').exec(text);
    return r ? r[1].trim() : null;
  }
  function blockOf(name) {
    const r = new RegExp('<' + name + '>([\\s\\S]*?)<\\/' + name + '>', 'i').exec(text);
    return r ? r[1] : null;
  }
  function tagIn(seg, name) {
    if (!seg) return null;
    const r = new RegExp('<' + name + '>([^<\\r\\n]+)', 'i').exec(seg);
    return r ? r[1].trim() : null;
  }
  function ofxDateToISO(v) {
    if (!v) return null;
    const s = String(v);
    if (s.length < 8) return null;
    return s.slice(0, 4) + '-' + s.slice(4, 6) + '-' + s.slice(6, 8);
  }
  const ledSeg = blockOf('LEDGERBAL');
  const availSeg = blockOf('AVAILBAL');
  const ledAmt = tagIn(ledSeg, 'BALAMT');
  const availAmt = tagIn(availSeg, 'BALAMT');
  const ledDt = tagIn(ledSeg, 'DTASOF');
  const availDt = tagIn(availSeg, 'DTASOF');
  return {
    ledger_balance: ledAmt !== null ? parseFloat(ledAmt) : null,
    available_balance: availAmt !== null ? parseFloat(availAmt) : null,
    balance_as_of: ofxDateToISO(ledDt || availDt),
    account_id: tagGlobal('ACCTID'),
    account_type: tagGlobal('ACCTTYPE'),
    currency: tagGlobal('CURDEF')
  };
}

function parseCSV(text) {
  const lines = text.split(/\r?\n/).filter(l => l.trim());
  if (lines.length < 2) return [];
  function splitCsv(line) {
    const out = [];
    let cur = '', inQ = false;
    for (let i = 0; i < line.length; i++) {
      const c = line[i];
      if (inQ) {
        if (c === '"' && line[i+1] === '"') { cur += '"'; i++; }
        else if (c === '"') inQ = false;
        else cur += c;
      } else {
        if (c === '"') inQ = true;
        else if (c === ',') { out.push(cur); cur = ''; }
        else cur += c;
      }
    }
    out.push(cur);
    return out.map(s => s.trim());
  }
  const headers = splitCsv(lines[0]).map(h => h.toLowerCase());
  function colIdx(...candidates) { for (const c of candidates) { const i = headers.indexOf(c); if (i >= 0) return i; } return -1; }
  const dateIdx = colIdx('date', 'posted', 'transaction date', 'post date');
  const amtIdx = colIdx('amount');
  const debitIdx = colIdx('debit');
  const creditIdx = colIdx('credit');
  const nameIdx = colIdx('description', 'payee', 'name', 'memo');
  const idIdx = colIdx('id', 'reference', 'transaction id', 'fitid');
  const txs = [];
  for (let r = 1; r < lines.length; r++) {
    const cols = splitCsv(lines[r]);
    let amount = null;
    if (amtIdx >= 0 && cols[amtIdx]) amount = parseFloat(cols[amtIdx].replace(/[$,\\s]/g, ''));
    else if (debitIdx >= 0 && cols[debitIdx]) amount = -Math.abs(parseFloat(cols[debitIdx].replace(/[$,\\s]/g, '')));
    else if (creditIdx >= 0 && cols[creditIdx]) amount = Math.abs(parseFloat(cols[creditIdx].replace(/[$,\\s]/g, '')));
    txs.push({
      fitid: idIdx >= 0 ? cols[idIdx] : null,
      type: null,
      amount,
      posted: dateIdx >= 0 ? cols[dateIdx] : null,
      name: nameIdx >= 0 ? cols[nameIdx] : null,
      memo: null
    });
  }
  return txs;
}

function institutionFromPath(p) {
  const rel = path.relative(IN_DIR, p);
  const first = rel.split(path.sep)[0];
  if (first && first !== path.basename(p)) return first.toLowerCase();
  const base = path.basename(p);
  return (base.split('-')[0] || 'unknown').toLowerCase();
}

function writeBalanceFile(inst, sourceFile, balance) {
  const instDir = path.join(OUT_DIR, inst);
  try { fs.mkdirSync(instDir, { recursive: true }); } catch (_) {}
  const out = {
    institution: inst,
    source_file: sourceFile,
    captured_at: new Date().toISOString(),
    ...balance
  };
  try { fs.writeFileSync(path.join(instDir, '_balance.json'), JSON.stringify(out, null, 2)); return true; } catch (_) { return false; }
}

// ---- Backfill pass: any existing institution missing _balance.json gets
//      its balance from the most recent matching archived file.
function backfillFromProcessed() {
  const filled = [];
  let instances;
  try { instances = fs.readdirSync(OUT_DIR); } catch (_) { return filled; }
  let processedFiles = [];
  try { processedFiles = fs.readdirSync(PROCESSED_DIR); } catch (_) {}
  for (const inst of instances) {
    const balPath = path.join(OUT_DIR, inst, '_balance.json');
    if (fs.existsSync(balPath)) continue;
    // Find the most recent archived file whose basename slug matches inst.
    const candidates = processedFiles
      .filter(f => f.toLowerCase().startsWith(inst))
      .map(f => ({ name: f, mtime: fs.statSync(path.join(PROCESSED_DIR, f)).mtimeMs }))
      .sort((a, b) => b.mtime - a.mtime);
    if (candidates.length === 0) continue;
    const src = path.join(PROCESSED_DIR, candidates[0].name);
    if (!/\.(ofx|qfx)/i.test(src)) continue;
    let raw;
    try { raw = fs.readFileSync(src, 'utf8'); } catch (_) { continue; }
    const bal = parseOFXBalance(raw);
    if (bal.ledger_balance === null && bal.available_balance === null) continue;
    if (writeBalanceFile(inst, candidates[0].name, bal)) filled.push({ inst, source: candidates[0].name, ledger: bal.ledger_balance });
  }
  return filled;
}

const backfilled = backfillFromProcessed();

// ---- Normal new-file pass.
const files = [];
walk(IN_DIR, files);

const results = [];
for (const f of files) {
  let raw;
  try { raw = fs.readFileSync(f, 'utf8'); } catch (e) { results.push({ error: String(e), file: f }); continue; }
  const isOFX = /\.(ofx|qfx)$/i.test(f);
  const txs = isOFX ? parseOFX(raw) : parseCSV(raw);
  const inst = institutionFromPath(f);
  const instDir = path.join(OUT_DIR, inst);
  try { fs.mkdirSync(instDir, { recursive: true }); } catch (_) {}
  for (const t of txs) {
    const id = (t.fitid || ((t.posted || 'undated') + '-' + (t.amount || '0') + '-' + (t.name || 'unknown').slice(0, 24))).replace(/[^a-zA-Z0-9_-]/g, '_');
    const rec = {
      captured_at: new Date().toISOString(),
      source: 'bank-' + inst,
      institution: inst,
      source_file: path.basename(f),
      transaction: t
    };
    try { fs.writeFileSync(path.join(instDir, id + '.json'), JSON.stringify(rec, null, 2)); } catch (_) {}
  }
  // Phase 2B — extract + persist bank-authoritative balance for OFX/QFX.
  let balanceWritten = false;
  if (isOFX) {
    const bal = parseOFXBalance(raw);
    if (bal.ledger_balance !== null || bal.available_balance !== null) {
      balanceWritten = writeBalanceFile(inst, path.basename(f), bal);
    }
  }
  // Archive the source file.
  try {
    const dst = path.join(PROCESSED_DIR, path.basename(f) + '.' + Date.now());
    fs.renameSync(f, dst);
  } catch (_) {}
  results.push({ ingested: f, institution: inst, transactions: txs.length, balance_written: balanceWritten });
}

if (results.length === 0 && backfilled.length === 0) {
  return [{ json: { skipped: true, reason: 'no-new-files' } }];
}
if (results.length === 0) {
  return [{ json: { skipped: 'no-new-files', backfilled } }];
}
return results.map(r => ({ json: { ...r, backfilled } }));
